#!date=2026-11-11 21:17:23
#############################################


[Argument]
jkxi_enable = switch,true,false,tag=京喜-脚本开关

[Rewrite]
response if ${url} ~= /^https?:\/\/api\.m\.jd\.com\/client\.action\?functionId=lite_advertising/i then response.body.replace(/jdLiteAdvertisingVO/, "fmz200")
response if ${url} ~= /^https?:\/\/api\.m\.jd\.com\/client\.action\?functionId=lite_SmartPush/i then response.body.replace(/pushData/, "fmz200")


[Script]
response if ${url} ~= /^https?:\/\/api\.m\.jd\.com\/api\?functionId=delivery_show/i then script("https://raw.githubusercontent.com/fmz200/wool_scripts/main/Scripts/jingxiAd.js") with enable=${jkxi_enable}, tag="京喜", timeout=60, requires_body=true




[MITM]
hostname = api.m.jd.com
